import base64
DATA={}
DATA[2]=dict(w=77,h=111,x=43,y=-8,source_stride=96,b64='')
DATA[4]=dict(w=50,h=108,x=17,y=-12,source_stride=64,b64='')
DATA[6]=dict(w=71,h=111,x=29,y=-8,source_stride=92,b64='')
DATA[8]=dict(w=86,h=115,x=46,y=-8,source_stride=108,b64='')
DATA[10]=dict(w=59,h=111,x=26,y=-9,source_stride=76,b64='')
DATA[12]=dict(w=65,h=116,x=24,y=-4,source_stride=84,b64='')

def unpack_packbits(enc, expected):
    data=base64.b64decode(enc); out=bytearray(); i=0
    while i<len(data) and len(out)<expected:
        c=data[i]; i+=1
        if c&0x80: out.extend(b'\\0'*((c&0x7f)+1))
        else:
            n=c+1; out.extend(data[i:i+n]); i+=n
    assert len(out)==expected,(len(out),expected)
    return bytes(out)

def frame(n):
    d=DATA[n].copy(); d['padded']=unpack_packbits(d.pop('b64'),d['w']*d['h']); return d
